CREATE TABLE IF NOT EXISTS gis_phase371_boundary_intersections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, feature_id TEXT NOT NULL, boundary_level TEXT NOT NULL, boundary_id TEXT, intersection_status TEXT NOT NULL, overlap_ratio DOUBLE PRECISION, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(certification_version,feature_id,boundary_level)); CREATE INDEX IF NOT EXISTS idx_phase371_feature ON gis_phase371_boundary_intersections(certification_version,feature_id); CREATE INDEX IF NOT EXISTS idx_phase371_boundary ON gis_phase371_boundary_intersections(boundary_level,boundary_id);